{
  "status": "SUPPORTED",
  "task_summary": "Set up refreshment settings for two people near their seats and move the entertainment control to an accessible location.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "seat",
        "entity_kind": "REGION",
        "function": "Location where people sit to watch TV",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["armchair", "chair", "sofa"],
        "required_properties": ["stable", "upright"]
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Container for drink or snack for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "mug", "plate", "bowl"],
        "required_properties": ["holds_liquid_or_food", "portable"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device to operate the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller", "phone"],
        "required_properties": ["wireless", "operates_tv"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Flat area to hold refreshment settings",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "side_table", "coffee_table", "desk"],
        "required_properties": ["flat", "stable"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Screen to be watched",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv", "monitor", "screen"],
        "required_properties": ["display_video"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_proximity",
        "relation": "nearby",
        "participant_roles": ["refreshment_setting", "seat"],
        "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "accessible_to",
        "participant_roles": ["entertainment_control", "seat"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "set_refreshments",
        "operation": "place",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "move",
        "participant_roles": ["entertainment_control", "surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "seat": [
        {"label": "Left armchair", "visual_description": "Black cushioned chair with wooden frame"},
        {"label": "Right armchair", "visual_description": "Black cushioned chair with wooden frame"}
      ],
      "refreshment_setting": [
        {"label": "Red cup", "visual_description": "Mug on the desk"},
        {"label": "White plate", "visual_description": "Plate on the desk"}
      ],
      "entertainment_control": [
        {"label": "Remote", "visual_description": "Black remote control on the desk"}
      ],
      "surface": [
        {"label": "Left side table", "visual_description": "Small wooden table next to left chair"},
        {"label": "Right side table", "visual_description": "Small wooden table next to right chair"},
        {"label": "Coffee table", "visual_description": "Rectangular table with green top"},
        {"label": "Desk", "visual_description": "Large wooden desk on the right wall"}
      ],
      "television": [
        {"label": "Wall TV", "visual_description": "Black flat screen mounted on the wall"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_storage",
        "label": "Desk on right wall",
        "visual_description": "Large wooden desk with items on top",
        "reason": "Likely contains drawers or lower shelves that could hold additional refreshment items or spare remotes."
      },
      {
        "id": "tv_console",
        "label": "Console under TV",
        "visual_description": "Low wooden stand beneath the wall-mounted TV",
        "reason": "Could contain media devices or controls related to the entertainment system."
      },
      {
        "id": "side_tables_shelves",
        "label": "Shelves on side tables",
        "visual_description": "Lower levels of the side tables",
        "reason": "Open storage space that might hold extra cups or napkins."
      }
    ],
    "inspection_order": [
      "desk_storage",
      "tv_console",
      "side_tables_shelves"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
